DECLARE @missing int, @same int, @other int, @filled int;
SELECT @missing = COUNT(*) FROM #s s WHERE NOT EXISTS (SELECT 1 FROM dbo.Lake l WHERE l.lake_id = s.lake_id);
SELECT @same  = COUNT(*) FROM #s s JOIN dbo.Lake l ON l.lake_id = s.lake_id WHERE l.state_id = s.state_id;
SELECT @other = COUNT(*) FROM #s s JOIN dbo.Lake l ON l.lake_id = s.lake_id WHERE l.state_id <> s.state_id;

BEGIN TRAN;
UPDATE l SET state_id = s.state_id
FROM dbo.Lake l JOIN #s s ON s.lake_id = l.lake_id
WHERE l.state_id IS NULL OR LTRIM(l.state_id) = '';
SET @filled = @@ROWCOUNT;
COMMIT;

SELECT DB_NAME() AS db, (SELECT COUNT(*) FROM #s) AS in_file, @filled AS filled, @same AS already_same,
       @other AS kept_different, @missing AS lake_not_found;
SELECT s.province, COUNT(*) AS lakes_with_state_id
FROM #s s JOIN dbo.Lake l ON l.lake_id = s.lake_id AND l.state_id = s.state_id GROUP BY s.province;
-- spot checks: Fraser River (BC) 39325, Cold Lake (AB) 4309
SELECT lake_name, state_id FROM dbo.Lake WHERE state_id IN ('39325', '4309') ORDER BY lake_name;
DROP TABLE #s;
